package com.medtrack.transfer.entity; import com.medtrack.batch.entity.Batch; import com.medtrack.medicine.entity.Medicine; import com.medtrack.shared.model.BaseEntity; import jakarta.persistence.*;
@Entity @Table(name="stock_transfer_items") public class StockTransferItem extends BaseEntity {@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="transfer_id",nullable=false)private StockTransfer transfer;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="medicine_id",nullable=false)private Medicine medicine;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="batch_id")private Batch batch;@Column(name="requested_quantity",nullable=false)private int requestedQuantity;@Column(name="allocated_quantity",nullable=false)private int allocatedQuantity;@Column(name="picked_quantity",nullable=false)private int pickedQuantity;@Column(name="dispatched_quantity",nullable=false)private int dispatchedQuantity;@Column(name="received_quantity",nullable=false)private int receivedQuantity;@Column(name="damaged_quantity",nullable=false)private int damagedQuantity;protected StockTransferItem(){}public StockTransferItem(Medicine m,int q){medicine=m;requestedQuantity=q;}public StockTransferItem(Medicine m,Batch b,int q){medicine=m;batch=b;requestedQuantity=q;allocatedQuantity=q;}void setTransfer(StockTransfer t){transfer=t;}public void pick(int q){if(q!=allocatedQuantity)throw new IllegalArgumentException("Picked quantity must equal allocation");pickedQuantity=q;}public void dispatch(){if(pickedQuantity!=allocatedQuantity)throw new IllegalArgumentException("All allocated stock must be picked");dispatchedQuantity=pickedQuantity;}public void receive(int q,int damaged){if(q<0||damaged<0||q+damaged>dispatchedQuantity)throw new IllegalArgumentException("Invalid receipt quantities");receivedQuantity=q;damagedQuantity=damaged;}public Batch getBatch(){return batch;}public Medicine getMedicine(){return medicine;}public int getRequestedQuantity(){return requestedQuantity;}public int getAllocatedQuantity(){return allocatedQuantity;}public int getPickedQuantity(){return pickedQuantity;}public int getDispatchedQuantity(){return dispatchedQuantity;}public int getReceivedQuantity(){return receivedQuantity;}public int getDamagedQuantity(){return damagedQuantity;} }
